   Q('note', 'A creole develops when __________ grow up speaking a pidgin as a first language', 'children', 'children start to grow up speaking it as their first language', 'Children turn it into a creole.', max=1),
   Q('note', 'Tok Pisin is spoken in Papua New __________', 'Guinea', 'Tok Pisin, spoken in Papua New Guinea', 'It is spoken in Papua New Guinea.', max=1),
   Q('note', 'Haitian Creole is based mainly on __________', 'French', 'which is based mainly on French', 'Its main source is French.', max=1),
